import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: './tests/setup.ts',
    css: true,
  },
});

export type SortDirection = 'asc' | 'desc';

export interface SortRule {
  columnId: string;
  direction: SortDirection;
}

export type FilterOperator =
  | 'eq'
  | 'neq'
  | 'gt'
  | 'gte'
  | 'lt'
  | 'lte'
  | 'contains'
  | 'notContains'
  | 'startsWith'
  | 'endsWith'
  | 'isEmpty'
  | 'isNotEmpty';

export interface FilterRule {
  columnId: string;
  operator: FilterOperator;
  value: string;
}

export interface ColumnDef<T = any> {
  id: string;
  header: string;
  accessor: keyof T | ((row: T) => any);
  width: number;
  minWidth?: number;
  maxWidth?: number;
  sortable?: boolean;
  filterable?: boolean;
  resizable?: boolean;
  editable?: boolean;
  cell?: (row: T) => React.ReactNode;
  editor?: (props: CellEditProps<T>) => React.ReactNode;
}

export interface CellEditProps<T = any> {
  value: any;
  row: T;
  rowIndex: number;
  column: ColumnDef<T>;
  onCommit: (value: any) => void;
  onCancel: () => void;
}

export interface EditingCell {
  rowIndex: number;
  columnId: string;
}

export type SelectionMode = 'single' | 'multi' | 'range';

export interface SelectionState {
  mode: SelectionMode;
  selectedIds: Set<string>;
  anchorIndex: number | null;
  rangeEndIndex: number | null;
}

export type DataSource = 'client' | 'server';

export interface DataTableProps<T = any> {
  data: T[];
  columns: ColumnDef<T>[];
  rowHeight?: number;
  overscan?: number;
  dataSource?: DataSource;
  selectionMode?: SelectionMode;
  selectedIds?: Set<string>;
  onSelectionChange?: (selectedIds: Set<string>) => void;
  idAccessor?: keyof T | ((row: T) => string);
  className?: string;
  height?: number | string;
  headerHeight?: number;
  filterHeight?: number;
  onSortChange?: (sortRules: SortRule[]) => void;
  onFilterChange?: (filterRules: FilterRule[]) => void;
  onColumnOrderChange?: (columnIds: string[]) => void;
  onColumnResize?: (columnId: string, width: number) => void;
  onCellEdit?: (rowIndex: number, columnId: string, value: any) => void;
  onExport?: (format: 'csv' | 'excel', data: T[], columns: ColumnDef<T>[]) => void;
  serverSort?: SortRule[];
  serverFilters?: FilterRule[];
  serverTotalRows?: number;
  loading?: boolean;
  locale?: string;
  ariaLabel?: string;
}

export interface TableBodyRef {
  scrollToRow: (index: number) => void;
  scrollToTop: () => void;
  getScrollPosition: () => number;
  focusCell: (rowIndex: number, columnIndex: number) => void;
}

import type { SortRule, FilterRule, ColumnDef, SortDirection } from './types';

export function getCellValue<T>(row: T, column: ColumnDef<T>): any {
  if (typeof column.accessor === 'function') {
    return column.accessor(row);
  }
  return row[column.accessor];
}

export function stableSort<T>(data: T[], sortRules: SortRule[], columns: ColumnDef<T>[]): T[] {
  if (!sortRules.length) return [...data];

  const colMap = new Map(columns.map((c) => [c.id, c]));

  return [...data].sort((a, b) => {
    for (const rule of sortRules) {
      const col = colMap.get(rule.columnId);
      if (!col) continue;
      const aVal = getCellValue(a, col);
      const bVal = getCellValue(b, col);

      const cmp = compareValues(aVal, bVal);
      if (cmp !== 0) {
        return rule.direction === 'asc' ? cmp : -cmp;
      }
    }
    return 0;
  });
}

function compareValues(a: any, b: any): number {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;

  if (typeof a === 'number' && typeof b === 'number') return a - b;
  if (typeof a === 'string' && typeof b === 'string') return a.localeCompare(b, undefined, { sensitivity: 'base' });
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();

  const aStr = String(a);
  const bStr = String(b);
  return aStr.localeCompare(bStr, undefined, { sensitivity: 'base' });
}

export function clientFilter<T>(data: T[], filterRules: FilterRule[], columns: ColumnDef<T>[]): T[] {
  if (!filterRules.length) return data;

  const colMap = new Map(columns.map((c) => [c.id, c]));

  return data.filter((row) => {
    for (const rule of filterRules) {
      const col = colMap.get(rule.columnId);
      if (!col) continue;
      const cellValue = getCellValue(row, col);
      if (!matchesFilter(cellValue, rule)) return false;
    }
    return true;
  });
}

function matchesFilter(value: any, rule: FilterRule): boolean {
  const strVal = value == null ? '' : String(value);
  const filterVal = rule.value;

  switch (rule.operator) {
    case 'eq':
      return strVal === filterVal;
    case 'neq':
      return strVal !== filterVal;
    case 'gt':
      return Number(value) > Number(filterVal);
    case 'gte':
      return Number(value) >= Number(filterVal);
    case 'lt':
      return Number(value) < Number(filterVal);
    case 'lte':
      return Number(value) <= Number(filterVal);
    case 'contains':
      return strVal.toLowerCase().includes(filterVal.toLowerCase());
    case 'notContains':
      return !strVal.toLowerCase().includes(filterVal.toLowerCase());
    case 'startsWith':
      return strVal.toLowerCase().startsWith(filterVal.toLowerCase());
    case 'endsWith':
      return strVal.toLowerCase().endsWith(filterVal.toLowerCase());
    case 'isEmpty':
      return strVal.trim() === '';
    case 'isNotEmpty':
      return strVal.trim() !== '';
    default:
      return true;
  }
}

export function cycleSortDirection(
  current: SortDirection | null,
  multiSort: boolean
): SortDirection | null {
  if (!current) return 'asc';
  if (multiSort && current === 'asc') return 'desc';
  if (multiSort && current === 'desc') return null;
  if (!multiSort && current === 'asc') return 'desc';
  if (!multiSort && current === 'desc') return 'asc';
  return null;
}

export function generateId(): string {
  return `row_${Math.random().toString(36).slice(2, 11)}_${Date.now().toString(36)}`;
}

export function exportToCSV<T>(data: T[], columns: ColumnDef<T>[], filename: string = 'export.csv'): void {
  const headers = columns.map((c) => c.header).join(',');
  const rows = data.map((row) =>
    columns
      .map((col) => {
        const val = getCellValue(row, col);
        const str = val == null ? '' : String(val);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
          return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
      })
      .join(',')
  );
  const csv = [headers, ...rows].join('\n');
  downloadBlob(csv, filename, 'text/csv;charset=utf-8;');
}

export function exportToExcel<T>(data: T[], columns: ColumnDef<T>[], filename: string = 'export.xlsx'): void {
  let html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Sheet1</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table>`;
  html += '<tr>' + columns.map((c) => `<th>${escapeHtml(c.header)}</th>`).join('') + '</tr>';
  for (const row of data) {
    html += '<tr>' + columns.map((col) => `<td>${escapeHtml(String(getCellValue(row, col) ?? ''))}</td>`).join('') + '</tr>';
  }
  html += '</table></body></html>';
  downloadBlob(html, filename, 'application/vnd.ms-excel');
}

function escapeHtml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function downloadBlob(content: string, filename: string, mimeType: string): void {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

import { useRef, useCallback, useState, useMemo, useEffect } from 'react';

interface VirtualScrollOptions {
  totalRows: number;
  rowHeight: number;
  overscan: number;
  containerHeight: number;
}

interface VirtualScrollResult {
  startIndex: number;
  endIndex: number;
  visibleRows: number[];
  totalHeight: number;
  offsetY: number;
  scrollTop: number;
  containerRef: React.RefCallback<HTMLDivElement>;
  scrollToIndex: (index: number) => void;
}

export function useVirtualScroll({
  totalRows,
  rowHeight,
  overscan,
  containerHeight,
}: VirtualScrollOptions): VirtualScrollResult {
  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement | null>(null);

  const totalHeight = totalRows * rowHeight;

  const setContainerRef = useCallback((node: HTMLDivElement | null) => {
    containerRef.current = node;
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const handleScroll = () => {
      setScrollTop(el.scrollTop);
    };

    el.addEventListener('scroll', handleScroll, { passive: true });
    return () => el.removeEventListener('scroll', handleScroll);
  }, []);

  const startIndex = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
  const visibleCount = Math.ceil(containerHeight / rowHeight) + overscan * 2;
  const endIndex = Math.min(totalRows, startIndex + visibleCount);
  const offsetY = startIndex * rowHeight;

  const visibleRows = useMemo(() => {
    const rows: number[] = [];
    for (let i = startIndex; i < endIndex; i++) {
      rows.push(i);
    }
    return rows;
  }, [startIndex, endIndex]);

  const scrollToIndex = useCallback(
    (index: number) => {
      const el = containerRef.current;
      if (!el) return;
      const target = Math.max(0, Math.min(index * rowHeight, totalHeight - containerHeight));
      el.scrollTop = target;
    },
    [rowHeight, totalHeight, containerHeight]
  );

  return {
    startIndex,
    endIndex,
    visibleRows,
    totalHeight,
    offsetY,
    scrollTop,
    containerRef: setContainerRef,
    scrollToIndex,
  };
}

import { useCallback, useMemo, useState } from 'react';
import type { SortRule, SortDirection } from './types';

interface UseSortingOptions {
  externalSort?: SortRule[];
  onSortChange?: (sortRules: SortRule[]) => void;
}

export function useSorting({ externalSort, onSortChange }: UseSortingOptions = {}) {
  const [internalSort, setInternalSort] = useState<SortRule[]>([]);

  const sortRules = externalSort ?? internalSort;

  const toggleSort = useCallback(
    (columnId: string, multiSort: boolean = false) => {
      const update = (prev: SortRule[]) => {
        const existingIdx = prev.findIndex((r) => r.columnId === columnId);

        if (existingIdx >= 0) {
          const existing = prev[existingIdx];
          if (existing.direction === 'asc') {
            const updated = [...prev];
            updated[existingIdx] = { columnId, direction: 'desc' as SortDirection };
            return updated;
          } else {
            return prev.filter((r) => r.columnId !== columnId);
          }
        }

        if (!multiSort) {
          return [{ columnId, direction: 'asc' as SortDirection }];
        }

        return [...prev, { columnId, direction: 'asc' as SortDirection }];
      };

      if (externalSort !== undefined) {
        const next = update(sortRules);
        onSortChange?.(next);
      } else {
        setInternalSort((prev) => update(prev));
      }
    },
    [externalSort, sortRules, onSortChange]
  );

  const clearSort = useCallback(() => {
    if (externalSort !== undefined) {
      onSortChange?.([]);
    } else {
      setInternalSort([]);
    }
  }, [externalSort, onSortChange]);

  const sortMap = useMemo(() => {
    const map = new Map<string, SortDirection>();
    sortRules.forEach((r) => map.set(r.columnId, r.direction));
    return map;
  }, [sortRules]);

  return { sortRules, sortMap, toggleSort, clearSort, setInternalSort };
}

import { useCallback, useState } from 'react';
import type { FilterRule, FilterOperator } from './types';

interface UseFilteringOptions {
  externalFilters?: FilterRule[];
  onFilterChange?: (filterRules: FilterRule[]) => void;
}

export function useFiltering({ externalFilters, onFilterChange }: UseFilteringOptions = {}) {
  const [internalFilters, setInternalFilters] = useState<FilterRule[]>([]);

  const filterRules = externalFilters ?? internalFilters;

  const setFilter = useCallback(
    (columnId: string, operator: FilterOperator, value: string) => {
      const update = (prev: FilterRule[]) => {
        const existingIdx = prev.findIndex((r) => r.columnId === columnId);
        if (existingIdx >= 0) {
          if (value === '') {
            return prev.filter((r) => r.columnId !== columnId);
          }
          const updated = [...prev];
          updated[existingIdx] = { columnId, operator, value };
          return updated;
        }
        if (value === '') return prev;
        return [...prev, { columnId, operator, value }];
      };

      if (externalFilters !== undefined) {
        const next = update(filterRules);
        onFilterChange?.(next);
      } else {
        setInternalFilters((prev) => update(prev));
      }
    },
    [externalFilters, filterRules, onFilterChange]
  );

  const clearFilters = useCallback(() => {
    if (externalFilters !== undefined) {
      onFilterChange?.([]);
    } else {
      setInternalFilters([]);
    }
  }, [externalFilters, onFilterChange]);

  const clearColumnFilter = useCallback(
    (columnId: string) => {
      setFilter(columnId, 'contains', '');
    },
    [setFilter]
  );

  return { filterRules, setFilter, clearFilters, clearColumnFilter };
}

import { useCallback, useState, useRef } from 'react';
import type { SelectionMode } from './types';

interface UseSelectionOptions {
  mode: SelectionMode;
  dataLength: number;
  idAccessor: (index: number) => string;
  externalSelected?: Set<string>;
  onSelectionChange?: (selectedIds: Set<string>) => void;
}

export function useSelection({
  mode,
  dataLength,
  idAccessor,
  externalSelected,
  onSelectionChange,
}: UseSelectionOptions) {
  const [internalSelected, setInternalSelected] = useState<Set<string>>(new Set());
  const [anchorIndex, setAnchorIndex] = useState<number | null>(null);
  const lastClickedRef = useRef<number | null>(null);

  const selectedIds = externalSelected ?? internalSelected;

  const setSelected = useCallback(
    (next: Set<string>) => {
      if (externalSelected !== undefined) {
        onSelectionChange?.(next);
      } else {
        setInternalSelected(next);
      }
    },
    [externalSelected, onSelectionChange]
  );

  const isSelected = useCallback(
    (index: number): boolean => {
      return selectedIds.has(idAccessor(index));
    },
    [selectedIds, idAccessor]
  );

  const toggleRow = useCallback(
    (index: number, event?: React.MouseEvent | React.KeyboardEvent) => {
      const id = idAccessor(index);

      if (mode === 'single') {
        setSelected(new Set([id]));
        setAnchorIndex(index);
        return;
      }

      if (mode === 'range' && event?.shiftKey && anchorIndex != null) {
        const start = Math.min(anchorIndex, index);
        const end = Math.max(anchorIndex, index);
        const newSet = new Set<string>();
        for (let i = start; i <= end; i++) {
          newSet.add(idAccessor(i));
        }
        if (event?.ctrlKey || event?.metaKey) {
          const union = new Set(selectedIds);
          newSet.forEach((id) => union.add(id));
          setSelected(union);
        } else {
          setSelected(newSet);
        }
        setAnchorIndex(index);
        return;
      }

      if (mode === 'multi' && (event?.ctrlKey || event?.metaKey)) {
        const newSet = new Set(selectedIds);
        if (newSet.has(id)) {
          newSet.delete(id);
        } else {
          newSet.add(id);
        }
        setSelected(newSet);
        setAnchorIndex(index);
        return;
      }

      const newSet = new Set<string>();
      newSet.add(id);
      setSelected(newSet);
      setAnchorIndex(index);
    },
    [mode, anchorIndex, selectedIds, idAccessor, setSelected]
  );

  const selectAll = useCallback(() => {
    if (mode === 'single') return;
    const allIds = new Set<string>();
    for (let i = 0; i < dataLength; i++) {
      allIds.add(idAccessor(i));
    }
    setSelected(allIds);
  }, [mode, dataLength, idAccessor, setSelected]);

  const clearSelection = useCallback(() => {
    setSelected(new Set());
    setAnchorIndex(null);
  }, [setSelected]);

  const selectRange = useCallback(
    (start: number, end: number) => {
      if (mode === 'single') return;
      const s = Math.min(start, end);
      const e = Math.max(start, end);
      const newSet = new Set<string>();
      for (let i = s; i <= e; i++) {
        newSet.add(idAccessor(i));
      }
      setSelected(newSet);
    },
    [mode, idAccessor, setSelected]
  );

  return {
    selectedIds,
    anchorIndex,
    isSelected,
    toggleRow,
    selectAll,
    clearSelection,
    selectRange,
    setSelected,
  };
}

import { useCallback, useRef, useState } from 'react';
import type { ColumnDef } from './types';

interface UseColumnResizeOptions {
  columns: ColumnDef[];
  onColumnResize?: (columnId: string, width: number) => void;
}

export function useColumnResize({ columns, onColumnResize }: UseColumnResizeOptions) {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>(() => {
    const widths: Record<string, number> = {};
    columns.forEach((col) => {
      widths[col.id] = col.width;
    });
    return widths;
  });

  const [resizing, setResizing] = useState<{
    columnId: string;
    startX: number;
    startWidth: number;
  } | null>(null);

  const resizeStart = useCallback(
    (columnId: string, event: React.MouseEvent) => {
      event.preventDefault();
      event.stopPropagation();
      const currentWidth = columnWidths[columnId] || columns.find((c) => c.id === columnId)?.width || 100;
      setResizing({ columnId, startX: event.clientX, startWidth: currentWidth });
    },
    [columnWidths, columns]
  );

  const resizeMove = useCallback(
    (event: MouseEvent) => {
      if (!resizing) return;
      const delta = event.clientX - resizing.startX;
      const newWidth = Math.max(50, resizing.startWidth + delta);
      const col = columns.find((c) => c.id === resizing.columnId);
      const clamped = col?.maxWidth ? Math.min(newWidth, col.maxWidth) : newWidth;
      const final = col?.minWidth ? Math.max(clamped, col.minWidth) : clamped;

      setColumnWidths((prev) => ({ ...prev, [resizing.columnId]: final }));
    },
    [resizing, columns]
  );

  const resizeEnd = useCallback(() => {
    if (resizing) {
      onColumnResize?.(resizing.columnId, columnWidths[resizing.columnId]);
    }
    setResizing(null);
  }, [resizing, columnWidths, onColumnResize]);

  const updateColumnWidths = useCallback((newColumns: ColumnDef[]) => {
    const widths: Record<string, number> = {};
    newColumns.forEach((col) => {
      widths[col.id] = col.width;
    });
    setColumnWidths(widths);
  }, []);

  return {
    columnWidths,
    resizing,
    resizeStart,
    resizeMove,
    resizeEnd,
    updateColumnWidths,
  };
}

import { useCallback, useRef } from 'react';

interface UseKeyboardNavigationOptions {
  totalRows: number;
  totalCols: number;
  onCellEdit?: (rowIndex: number, colIndex: number) => void;
  onSelectRow?: (rowIndex: number, event: React.KeyboardEvent) => void;
  onSelectAll?: () => void;
  scrollToRow?: (rowIndex: number) => void;
  containerRef: React.RefObject<HTMLDivElement | null>;
}

export function useKeyboardNavigation({
  totalRows,
  totalCols,
  onCellEdit,
  onSelectRow,
  onSelectAll,
  scrollToRow,
  containerRef,
}: UseKeyboardNavigationOptions) {
  const focusState = useRef({ row: 0, col: 0 });

  const moveFocus = useCallback(
    (rowDelta: number, colDelta: number) => {
      const next = focusState.current;
      const newRow = Math.max(0, Math.min(totalRows - 1, next.row + rowDelta));
      const newCol = Math.max(0, Math.min(totalCols - 1, next.col + colDelta));
      focusState.current = { row: newRow, col: newCol };

      if (rowDelta !== 0) {
        scrollToRow?.(newRow);
      }

      const activeElement = document.activeElement as HTMLElement;
      if (activeElement) {
        activeElement.blur();
      }

      requestAnimationFrame(() => {
        const cell = containerRef.current?.querySelector(
          `[data-row-index="${newRow}"][data-col-index="${newCol}"]`
        ) as HTMLElement;
        cell?.focus();
      });
    },
    [totalRows, totalCols, scrollToRow, containerRef]
  );

  const setFocusedCell = useCallback((row: number, col: number) => {
    focusState.current = { row, col };
  }, []);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      const { row, col } = focusState.current;
      let handled = true;

      switch (event.key) {
        case 'ArrowUp':
          moveFocus(-1, 0);
          event.preventDefault();
          break;
        case 'ArrowDown':
          moveFocus(1, 0);
          event.preventDefault();
          break;
        case 'ArrowLeft':
          moveFocus(0, -1);
          event.preventDefault();
          break;
        case 'ArrowRight':
          moveFocus(0, 1);
          event.preventDefault();
          break;
        case 'Home':
          if (event.ctrlKey) {
            moveFocus(-row, -col);
          } else {
            moveFocus(0, -col);
          }
          event.preventDefault();
          break;
        case 'End':
          if (event.ctrlKey) {
            moveFocus(totalRows - 1 - row, totalCols - 1 - col);
          } else {
            moveFocus(0, totalCols - 1 - col);
          }
          event.preventDefault();
          break;
        case 'PageUp':
          moveFocus(-20, 0);
          event.preventDefault();
          break;
        case 'PageDown':
          moveFocus(20, 0);
          event.preventDefault();
          break;
        case 'Enter':
        case 'F2':
          if (onCellEdit) {
            onCellEdit(row, col);
          }
          event.preventDefault();
          break;
        case ' ':
          if (onSelectRow) {
            onSelectRow(row, event);
          }
          event.preventDefault();
          break;
        case 'a':
          if (event.ctrlKey && onSelectAll) {
            onSelectAll();
            event.preventDefault();
          }
          break;
        default:
          handled = false;
      }

      if (handled) {
        event.stopPropagation();
      }
    },
    [totalRows, totalCols, moveFocus, onCellEdit, onSelectRow, onSelectAll]
  );

  return { handleKeyDown, moveFocus, setFocusedCell, focusState };
}

import { useCallback, useState } from 'react';
import type { EditingCell } from './types';

interface UseInlineEditOptions {
  onCellEdit?: (rowIndex: number, columnId: string, value: any) => void;
}

export function useInlineEdit({ onCellEdit }: UseInlineEditOptions = {}) {
  const [editingCell, setEditingCell] = useState<EditingCell | null>(null);

  const startEdit = useCallback((rowIndex: number, columnId: string) => {
    setEditingCell({ rowIndex, columnId });
  }, []);

  const commitEdit = useCallback(
    (value: any) => {
      if (editingCell) {
        onCellEdit?.(editingCell.rowIndex, editingCell.columnId, value);
        setEditingCell(null);
      }
    },
    [editingCell, onCellEdit]
  );

  const cancelEdit = useCallback(() => {
    setEditingCell(null);
  }, []);

  const isEditing = useCallback(
    (rowIndex: number, columnId: string): boolean => {
      return editingCell?.rowIndex === rowIndex && editingCell?.columnId === columnId;
    },
    [editingCell]
  );

  return { editingCell, startEdit, commitEdit, cancelEdit, isEditing };
}

import { useCallback, useState, useRef } from 'react';

interface UseColumnReorderOptions {
  columnIds: string[];
  onColumnOrderChange?: (columnIds: string[]) => void;
}

export function useColumnReorder({ columnIds, onColumnOrderChange }: UseColumnReorderOptions) {
  const [draggedColumn, setDraggedColumn] = useState<string | null>(null);
  const [dropTarget, setDropTarget] = useState<{ columnId: string; position: 'before' | 'after' } | null>(null);
  const dragOverRef = useRef<number>(0);

  const handleDragStart = useCallback(
    (columnId: string, event: React.DragEvent) => {
      setDraggedColumn(columnId);
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', columnId);
    },
    []
  );

  const handleDragOver = useCallback(
    (columnId: string, event: React.DragEvent) => {
      event.preventDefault();
      if (!draggedColumn || draggedColumn === columnId) return;

      const rect = (event.currentTarget as HTMLElement).getBoundingClientRect();
      const mid = rect.left + rect.width / 2;
      const position = event.clientX < mid ? 'before' : 'after';

      setDropTarget({ columnId, position });
    },
    [draggedColumn]
  );

  const handleDrop = useCallback(
    (targetColumnId: string, event: React.DragEvent) => {
      event.preventDefault();
      if (!draggedColumn || draggedColumn === targetColumnId) {
        setDraggedColumn(null);
        setDropTarget(null);
        return;
      }

      const rect = (event.currentTarget as HTMLElement).getBoundingClientRect();
      const mid = rect.left + rect.width / 2;
      const position: 'before' | 'after' = event.clientX < mid ? 'before' : 'after';

      const reordered = [...columnIds];
      const dragIdx = reordered.indexOf(draggedColumn);
      let targetIdx = reordered.indexOf(targetColumnId);

      if (dragIdx >= 0 && targetIdx >= 0) {
        reordered.splice(dragIdx, 1);
        if (position === 'after') targetIdx++;
        if (dragIdx < targetIdx) targetIdx--;
        reordered.splice(Math.max(0, targetIdx), 0, draggedColumn);
      }

      onColumnOrderChange?.(reordered);

      setDraggedColumn(null);
      setDropTarget(null);
    },
    [draggedColumn, columnIds, onColumnOrderChange]
  );

  const handleDragEnd = useCallback(() => {
    setDraggedColumn(null);
    setDropTarget(null);
  }, []);

  const reorderColumns = useCallback(
    (fromIndex: number, toIndex: number) => {
      const reordered = [...columnIds];
      const [moved] = reordered.splice(fromIndex, 1);
      reordered.splice(toIndex, 0, moved);
      onColumnOrderChange?.(reordered);
      return reordered;
    },
    [columnIds, onColumnOrderChange]
  );

  return {
    draggedColumn,
    dropTarget,
    handleDragStart,
    handleDragOver,
    handleDrop,
    handleDragEnd,
    reorderColumns,
  };
}

import React, { useMemo, useCallback, useRef, useImperativeHandle, forwardRef } from 'react';
import type {
  DataTableProps,
  ColumnDef,
  TableBodyRef,
} from './types';
import { useVirtualScroll } from './useVirtualScroll';
import { useSorting } from './useSorting';
import { useFiltering } from './useFiltering';
import { useSelection } from './useSelection';
import { useColumnResize } from './useColumnResize';
import { useColumnReorder } from './useColumnReorder';
import { useKeyboardNavigation } from './useKeyboardNavigation';
import { useInlineEdit } from './useInlineEdit';
import { stableSort, clientFilter, getCellValue, exportToCSV, exportToExcel } from './utils';
import './styles.css';

const DEFAULT_ROW_HEIGHT = 36;
const DEFAULT_HEADER_HEIGHT = 40;
const DEFAULT_FILTER_HEIGHT = 36;
const DEFAULT_OVERSCAN = 10;

function DataTableInner<T extends Record<string, any>>(
  props: DataTableProps<T>,
  ref: React.ForwardedRef<TableBodyRef>
) {
  const {
    data,
    columns: columnsProp,
    rowHeight = DEFAULT_ROW_HEIGHT,
    overscan = DEFAULT_OVERSCAN,
    dataSource = 'client',
    selectionMode = 'multi',
    selectedIds: externalSelected,
    onSelectionChange,
    idAccessor: idAccessorProp,
    className,
    height: heightProp,
    headerHeight = DEFAULT_HEADER_HEIGHT,
    filterHeight = DEFAULT_FILTER_HEIGHT,
    onSortChange,
    onFilterChange,
    onColumnOrderChange,
    onColumnResize,
    onCellEdit,
    onExport,
    serverSort,
    serverFilters,
    serverTotalRows,
    loading = false,
    locale = 'en-US',
    ariaLabel = 'Data Table',
  } = props;

  const containerRef = useRef<HTMLDivElement>(null);
  const tableRef = useRef<HTMLTableElement>(null);

  const [columnOrder, setColumnOrder] = React.useState<string[]>(() => columnsProp.map((c) => c.id));
  const [containerHeight, setContainerHeight] = React.useState(600);

  const idAccessor = useCallback(
    (index: number): string => {
      if (idAccessorProp) {
        const row = data[index];
        if (typeof idAccessorProp === 'function') return idAccessorProp(row);
        return String(row[idAccessorProp] ?? index);
      }
      return String(index);
    },
    [data, idAccessorProp]
  );

  const columnMap = useMemo(() => {
    const map = new Map<string, ColumnDef<T>>();
    columnsProp.forEach((c) => map.set(c.id, c));
    return map;
  }, [columnsProp]);

  const orderedColumns = useMemo(() => {
    return columnOrder.map((id) => columnMap.get(id)!).filter(Boolean);
  }, [columnOrder, columnMap]);

  const {
    sortRules,
    sortMap,
    toggleSort,
    clearSort,
  } = useSorting({
    externalSort: dataSource === 'server' ? serverSort : undefined,
    onSortChange,
  });

  const {
    filterRules,
    setFilter,
    clearFilters,
  } = useFiltering({
    externalFilters: dataSource === 'server' ? serverFilters : undefined,
    onFilterChange,
  });

  const processedData = useMemo(() => {
    if (dataSource === 'server') return data;
    let result = clientFilter(data, filterRules, columnsProp);
    result = stableSort(result, sortRules, columnsProp);
    return result;
  }, [data, filterRules, sortRules, columnsProp, dataSource]);

  const totalRows = dataSource === 'server' ? (serverTotalRows ?? data.length) : processedData.length;

  const containerHeightCalc = useMemo(() => {
    if (typeof heightProp === 'number') return heightProp;
    if (heightProp) {
      try {
        const parsed = parseFloat(heightProp);
        return isNaN(parsed) ? 600 : parsed;
      } catch {
        return 600;
      }
    }
    return containerHeight;
  }, [heightProp, containerHeight]);

  React.useEffect(() => {
    if (!heightProp && containerRef.current) {
      const observer = new ResizeObserver((entries) => {
        for (const entry of entries) {
          setContainerHeight(entry.contentRect.height);
        }
      });
      observer.observe(containerRef.current);
      return () => observer.disconnect();
    }
  }, [heightProp]);

  const {
    startIndex,
    endIndex,
    visibleRows,
    totalHeight,
    offsetY,
    scrollTop,
    containerRef: virtualContainerRef,
    scrollToIndex,
  } = useVirtualScroll({
    totalRows,
    rowHeight,
    overscan,
    containerHeight: containerHeightCalc - headerHeight - filterHeight - 2,
  });

  const {
    selectedIds,
    isSelected,
    toggleRow,
    selectAll,
    clearSelection,
  } = useSelection({
    mode: selectionMode,
    dataLength: totalRows,
    idAccessor,
    externalSelected,
    onSelectionChange,
  });

  const {
    columnWidths,
    resizing,
    resizeStart,
    resizeMove,
    resizeEnd,
    updateColumnWidths,
  } = useColumnResize({ columns: columnsProp, onColumnResize });

  React.useEffect(() => {
    updateColumnWidths(columnsProp);
  }, [columnsProp, updateColumnWidths]);

  const {
    draggedColumn,
    dropTarget,
    handleDragStart,
    handleDragOver,
    handleDrop,
    handleDragEnd,
  } = useColumnReorder({
    columnIds: columnOrder,
    onColumnOrderChange: (ids) => {
      setColumnOrder(ids);
      onColumnOrderChange?.(ids);
    },
  });

  const {
    editingCell,
    startEdit,
    commitEdit,
    cancelEdit,
    isEditing,
  } = useInlineEdit({ onCellEdit });

  const { handleKeyDown, setFocusedCell } = useKeyboardNavigation({
    totalRows,
    totalCols: orderedColumns.length,
    onCellEdit: (rowIdx, colIdx) => {
      const rowData = processedData[rowIdx];
      const col = orderedColumns[colIdx];
      if (col && col.editable) {
        startEdit(rowIdx, col.id);
      }
    },
    onSelectRow: (rowIdx, event) => {
      toggleRow(rowIdx, event as any);
    },
    onSelectAll: selectAll,
    scrollToRow: scrollToIndex,
    containerRef,
  });

  React.useEffect(() => {
    if (resizing) {
      const handleMouseMove = (e: MouseEvent) => resizeMove(e);
      const handleMouseUp = () => resizeEnd();
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
      };
    }
  }, [resizing, resizeMove, resizeEnd]);

  useImperativeHandle(
    ref,
    () => ({
      scrollToRow: scrollToIndex,
      scrollToTop: () => scrollToIndex(0),
      getScrollPosition: () => scrollTop,
      focusCell: (rowIdx: number, colIdx: number) => {
        setFocusedCell(rowIdx, colIdx);
      },
    }),
    [scrollToIndex, scrollTop, setFocusedCell]
  );

  const handleExportCSV = useCallback(() => {
    if (onExport) {
      onExport('csv', processedData, orderedColumns);
    } else {
      exportToCSV(processedData, orderedColumns);
    }
  }, [onExport, processedData, orderedColumns]);

  const handleExportExcel = useCallback(() => {
    if (onExport) {
      onExport('excel', processedData, orderedColumns);
    } else {
      exportToExcel(processedData, orderedColumns);
    }
  }, [onExport, processedData, orderedColumns]);

  const getSortIndicator = (columnId: string): string => {
    const dir = sortMap.get(columnId);
    if (!dir) return '\u2195';
    return dir === 'asc' ? '\u2191' : '\u2193';
  };

  const getSortTitle = (columnId: string): string => {
    const dir = sortMap.get(columnId);
    if (!dir) return 'Click to sort ascending';
    return dir === 'asc' ? 'Click to sort descending' : 'Click to remove sort';
  };

  return (
    <div
      className={`dt-container ${className ?? ''}`}
      role="grid"
      aria-label={ariaLabel}
      aria-rowcount={totalRows + 1}
      aria-colcount={orderedColumns.length}
      onKeyDown={handleKeyDown}
    >
      {loading && (
        <div className="dt-loading-overlay" role="alert" aria-busy="true">
          <div className="dt-spinner" />
        </div>
      )}

      <div className="dt-toolbar" role="toolbar" aria-label="Table toolbar">
        <div className="dt-toolbar-left">
          <span className="dt-row-count" aria-live="polite">
            {totalRows.toLocaleString(locale)} row{totalRows !== 1 ? 's' : ''}
            {selectedIds.size > 0 && ` (${selectedIds.size} selected)`}
          </span>
          {filterRules.length > 0 && (
            <button className="dt-btn dt-btn-sm" onClick={clearFilters} aria-label="Clear all filters">
              Clear Filters
            </button>
          )}
          {sortRules.length > 0 && (
            <button className="dt-btn dt-btn-sm" onClick={clearSort} aria-label="Clear all sorting">
              Clear Sort
            </button>
          )}
        </div>
        <div className="dt-toolbar-right">
          {selectionMode !== 'single' && totalRows > 0 && (
            <>
              <button className="dt-btn dt-btn-sm" onClick={selectAll} aria-label="Select all rows">
                Select All
              </button>
              <button className="dt-btn dt-btn-sm" onClick={clearSelection} aria-label="Clear selection">
                Clear
              </button>
            </>
          )}
          <button className="dt-btn dt-btn-sm" onClick={handleExportCSV} aria-label="Export to CSV">
            CSV
          </button>
          <button className="dt-btn dt-btn-sm" onClick={handleExportExcel} aria-label="Export to Excel">
            Excel
          </button>
        </div>
      </div>

      <div className="dt-table-wrapper" ref={containerRef}>
        <table
          ref={tableRef}
          className="dt-table"
          role="presentation"
          style={{ minWidth: orderedColumns.reduce((s, c) => s + (columnWidths[c.id] ?? c.width), 0) }}
        >
          <thead className="dt-thead">
            <tr className="dt-header-row dt-row-select" role="row" style={{ height: headerHeight }}>
              {(selectionMode === 'multi' || selectionMode === 'range') && (
                <th
                  className="dt-th dt-th-select"
                  style={{ width: 40 }}
                  role="columnheader"
                  aria-label="Select all"
                  scope="col"
                >
                  <input
                    type="checkbox"
                    checked={selectedIds.size > 0 && selectedIds.size === totalRows}
                    ref={(el) => {
                      if (el) el.indeterminate = selectedIds.size > 0 && selectedIds.size < totalRows;
                    }}
                    onChange={(e) => {
                      if (e.target.checked) selectAll();
                      else clearSelection();
                    }}
                    aria-label="Select all rows"
                  />
                </th>
              )}
              {orderedColumns.map((col, colIdx) => {
                const width = columnWidths[col.id] ?? col.width;
                const isDropBefore = dropTarget?.columnId === col.id && dropTarget?.position === 'before';
                const isDropAfter = dropTarget?.columnId === col.id && dropTarget?.position === 'after';
                return (
                  <th
                    key={col.id}
                    className={`dt-th ${draggedColumn === col.id ? 'dt-th-dragging' : ''} ${
                      isDropBefore ? 'dt-drop-before' : ''
                    } ${isDropAfter ? 'dt-drop-after' : ''}`}
                    style={{ width, minWidth: col.minWidth ?? 50, maxWidth: col.maxWidth }}
                    role="columnheader"
                    aria-sort={sortMap.has(col.id) ? (sortMap.get(col.id) === 'asc' ? 'ascending' : 'descending') : 'none'}
                    aria-label={`${col.header}${sortMap.has(col.id) ? ', sorted ' + sortMap.get(col.id) : ''}`}
                    scope="col"
                    draggable
                    onDragStart={(e) => handleDragStart(col.id, e)}
                    onDragOver={(e) => handleDragOver(col.id, e)}
                    onDrop={(e) => handleDrop(col.id, e)}
                    onDragEnd={handleDragEnd}
                  >
                    <div className="dt-th-content">
                      <span
                        className={`dt-header-text ${col.sortable !== false ? 'dt-sortable' : ''}`}
                        onClick={(e) => {
                          if (col.sortable !== false) {
                            toggleSort(col.id, e.ctrlKey || e.metaKey);
                          }
                        }}
                        title={col.sortable !== false ? getSortTitle(col.id) : undefined}
                        role={col.sortable !== false ? 'button' : undefined}
                        tabIndex={col.sortable !== false ? 0 : undefined}
                        onKeyDown={(e) => {
                          if ((e.key === 'Enter' || e.key === ' ') && col.sortable !== false) {
                            e.preventDefault();
                            toggleSort(col.id, e.ctrlKey || e.metaKey);
                          }
                        }}
                      >
                        {col.header}
                      </span>
                      {col.sortable !== false && (
                        <span className="dt-sort-indicator" aria-hidden="true">
                          {getSortIndicator(col.id)}
                        </span>
                      )}
                    </div>
                    {col.resizable !== false && (
                      <div
                        className="dt-resize-handle"
                        onMouseDown={(e) => resizeStart(col.id, e)}
                        role="separator"
                        aria-orientation="vertical"
                        aria-label={`Resize ${col.header} column`}
                        tabIndex={0}
                        onKeyDown={(e) => {
                          if (e.key === 'ArrowLeft') {
                            const newW = Math.max(col.minWidth ?? 50, (columnWidths[col.id] ?? col.width) - 10);
                            setColumnWidths();
                            onColumnResize?.(col.id, newW);
                          } else if (e.key === 'ArrowRight') {
                            const newW = Math.min(col.maxWidth ?? Infinity, (columnWidths[col.id] ?? col.width) + 10);
                            onColumnResize?.(col.id, newW);
                          }
                        }}
                      />
                    )}
                  </th>
                );
              })}
            </tr>

            {orderedColumns.some((c) => c.filterable !== false) && (
              <tr className="dt-filter-row" role="row" style={{ height: filterHeight }}>
                {(selectionMode === 'multi' || selectionMode === 'range') && (
                  <td className="dt-td dt-td-select" style={{ width: 40 }} />
                )}
                {orderedColumns.map((col) => (
                  <td
                    key={col.id}
                    className="dt-td dt-filter-cell"
                    style={{ width: columnWidths[col.id] ?? col.width }}
                  >
                    {col.filterable !== false && (
                      <input
                        className="dt-filter-input"
                        type="text"
                        placeholder={`Filter ${col.header}...`}
                        aria-label={`Filter by ${col.header}`}
                        value={filterRules.find((r) => r.columnId === col.id)?.value ?? ''}
                        onChange={(e) => setFilter(col.id, 'contains', e.target.value)}
                      />
                    )}
                  </td>
                ))}
              </tr>
            )}
          </thead>

          <tbody>
            <tr aria-hidden="true" style={{ height: offsetY }} />
            {visibleRows.map((rowIdx) => {
              const row = processedData[rowIdx];
              const selected = isSelected(rowIdx);
              const rowId = idAccessor(rowIdx);
              return (
                <tr
                  key={rowId}
                  className={`dt-row ${selected ? 'dt-row-selected' : ''} ${rowIdx % 2 === 1 ? 'dt-row-striped' : ''}`}
                  role="row"
                  aria-selected={selected}
                  aria-rowindex={rowIdx + 2}
                  style={{ height: rowHeight }}
                  onClick={(e) => toggleRow(rowIdx, e)}
                >
                  {(selectionMode === 'multi' || selectionMode === 'range') && (
                    <td className="dt-td dt-td-select" style={{ width: 40 }} role="gridcell">
                      {selectionMode === 'single' ? null : (
                        <input
                          type="checkbox"
                          checked={selected}
                          onChange={() => toggleRow(rowIdx)}
                          aria-label={`Select row ${rowIdx + 1}`}
                          tabIndex={-1}
                        />
                      )}
                    </td>
                  )}
                  {orderedColumns.map((col, colIdx) => {
                    const cellValue = getCellValue(row, col);
                    const editing = isEditing(rowIdx, col.id);
                    const width = columnWidths[col.id] ?? col.width;
                    return (
                      <td
                        key={col.id}
                        className={`dt-td ${editing ? 'dt-td-editing' : ''}`}
                        style={{ width, maxWidth: width }}
                        role="gridcell"
                        data-row-index={rowIdx}
                        data-col-index={colIdx}
                        tabIndex={-1}
                        onDoubleClick={() => {
                          if (col.editable) startEdit(rowIdx, col.id);
                        }}
                      >
                        {editing ? (
                          <InlineEditCell
                            value={cellValue}
                            row={row}
                            rowIndex={rowIdx}
                            column={col}
                            onCommit={commitEdit}
                            onCancel={cancelEdit}
                          />
                        ) : col.cell ? (
                          col.cell(row)
                        ) : (
                          <span className="dt-cell-value">{cellValue ?? ''}</span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>

        <div aria-hidden="true" style={{ height: totalHeight - offsetY - visibleRows.length * rowHeight }} />
      </div>

      {processingData.length === 0 && !loading && (
        <div className="dt-empty" role="status">
          No data to display
        </div>
      )}
    </div>
  );
}

interface InlineEditCellProps<T = any> {
  value: any;
  row: T;
  rowIndex: number;
  column: ColumnDef<T>;
  onCommit: (value: any) => void;
  onCancel: () => void;
}

function InlineEditCell<T>({ value, row, rowIndex, column, onCommit, onCancel }: InlineEditCellProps<T>) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [editValue, setEditValue] = React.useState(value ?? '');

  React.useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  if (column.editor) {
    return <>{column.editor({ value: editValue, row, rowIndex, column, onCommit, onCancel })}</>;
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      onCommit(editValue);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      onCancel();
    } else if (e.key === 'Tab') {
      e.preventDefault();
      onCommit(editValue);
    }
  };

  return (
    <input
      ref={inputRef}
      className="dt-inline-edit-input"
      value={editValue}
      onChange={(e) => setEditValue(e.target.value)}
      onKeyDown={handleKeyDown}
      onBlur={() => onCommit(editValue)}
      aria-label={`Edit ${column.header}`}
    />
  );
}

export const DataTable = forwardRef(DataTableInner) as <T extends Record<string, any>>(
  props: DataTableProps<T> & { ref?: React.ForwardedRef<TableBodyRef> }
) => React.ReactElement;

